import React, { useState, useEffect, useRef, useMemo, useCallback, useReducer, createContext, useContext, Component } from 'react';

function App() {
  const [showDetails, setShowDetails] = useState(false);
  const [name] = useState('Alice');

  if (showDetails) {
    const [bio] = useState('React developer from NYC');
    const [joined] = useState('January 2025');
  }

  return (
    <div>
      <h2 id="name">{name}</h2>
      <label>
        <input
          id="toggle"
          type="checkbox"
          checked={showDetails}
          onChange={(e) => setShowDetails(e.target.checked)}
        />
        Show Details
      </label>
      {showDetails && (
        <div id="details">
          <p id="bio">Bio: React developer from NYC</p>
          <p id="joined">Joined: January 2025</p>
        </div>
      )}
    </div>
  );
}

export default App;

