import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('The Conditional Hook', () => {
  test('Renders name without crashing', async () => {
    const { container: root } = render(<App />);
    const el = root.querySelector('#name');
if (!el) throw new Error('No #name element');
if (!el.textContent.includes('Alice')) throw new Error('Should show "Alice"');
  });

  test('Details hidden initially', async () => {
    const { container: root } = render(<App />);
    const details = root.querySelector('#details');
if (details) throw new Error('Details should be hidden initially');
  });

  test('Toggling checkbox shows details', async () => {
    const { container: root } = render(<App />);
    const toggle = root.querySelector('#toggle');
if (!toggle) throw new Error('No #toggle checkbox');
toggle.click();
const details = root.querySelector('#details');
if (!details) throw new Error('Details should be visible after toggle');
  });

  test('Details show bio and joined date', async () => {
    const { container: root } = render(<App />);
    const bio = root.querySelector('#bio');
const joined = root.querySelector('#joined');
if (!bio || !bio.textContent.includes('React developer'))
  throw new Error('Bio should contain "React developer"');
if (!joined || !joined.textContent.includes('January 2025'))
  throw new Error('Joined should contain "January 2025"');
  });

  test('Can toggle details off and on again', async () => {
    const { container: root } = render(<App />);
    const toggle = root.querySelector('#toggle');
toggle.click();
const details = root.querySelector('#details');
if (details) throw new Error('Details should hide when unchecked');
toggle.click();
const detailsAgain = root.querySelector('#details');
if (!detailsAgain) throw new Error('Details should show again');
  });
});
